const body = $input.item.json.body;
const entry = body.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];
const metadata = value?.metadata;

if (!message) {
  return [{ json: { skip: true, reason: 'no_message' } }];
}

if (message.type !== 'text') {
  return [{ json: { skip: true, reason: 'non_text' } }];
}

return [{
  json: {
    skip: false,
    phone: message.from,
    message: message.text?.body,
    businessPhoneId: metadata?.phone_number_id,
    displayPhoneNumber: metadata?.display_phone_number,
    messageId: message.id
  }
}];

const historyItems = $('Get Message History').all();
const professional = $('Get Professional Config').item.json;
const incoming = $('Extract WhatsApp Data').item.json;
const apiResponse = $('Registrar mensaje entrante (API)').item.json;

const businessName = professional.full_name || 'el negocio';
const businessConfig = professional.business_config || {};
const btConfig = professional.business_types?.config || {};
const tonePrompt = professional.tone_prompt || '';

// ── Construir menú como texto ──
const menuItems = businessConfig.menu || [];
let menuTexto = 'El menú no está configurado aún.';
if (menuItems.length > 0) {
  menuTexto = menuItems.map(cat => {
    const platillos = (cat.platillos || [])
      .filter(p => p.disponible !== false)
      .map(p => `  - ${p.nombre}: $${p.precio}`)
      .join('\n');
    return `*${cat.categoria}:*\n${platillos}`;
  }).join('\n\n');
}

// ── Horario ──
const workingHours = businessConfig.working_hours || btConfig.working_hours || {};
const diasTexto = Object.entries(workingHours)
  .map(([dia, h]) => `${dia}: ${h.start} - ${h.end}`)
  .join(', ');

const ahora = new Date();
const diasSemana = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
const diaActual = diasSemana[ahora.getDay()];
const horarioHoy = workingHours[diaActual];
let estaAbierto = true;
if (horarioHoy) {
  const [hA, mA] = horarioHoy.start.split(':').map(Number);
  const [hC, mC] = horarioHoy.end.split(':').map(Number);
  const minAhora = ahora.getHours() * 60 + ahora.getMinutes();
  estaAbierto = minAhora >= (hA * 60 + mA) && minAhora <= (hC * 60 + mC);
}

// ── System prompt ──
const systemPrompt = estaAbierto
  ? `Eres el asistente de pedidos de "${businessName}". ${tonePrompt}\n\nMENÚ DISPONIBLE:\n${menuTexto}\n\nHORARIO: ${diasTexto || 'Consulta directamente con el negocio'}\n\nINSTRUCCIONES CRÍTICAS:\n1. REVISA EL HISTORIAL COMPLETO antes de responder. Si el cliente ya mencionó platillos en mensajes anteriores, ese pedido sigue activo. NO lo olvides.\n2. NUNCA vuelvas a mostrar el menú si el cliente ya tiene platillos confirmados en el historial.\n3. Si ya tienes platillos + nombre + tipo de entrega + método de pago → ejecuta Create_Order INMEDIATAMENTE.\n4. Si tienes platillos pero faltan datos → pregunta SOLO por los datos que faltan, no por los que ya tienes.\n5. Si el cliente no ha pedido nada aún → muestra el menú y ayúdalo a ordenar.\n6. Sé conciso — máximo 3 oraciones por respuesta.\n7. Responde siempre en español.`
  : `Eres el asistente de "${businessName}". En este momento estamos cerrados. Horario: ${diasTexto}. Informa amablemente al cliente y dile cuándo puede volver a escribir.`;

// ── Formatear historial con roles correctos para OpenAI ──
// Usar 'direction' para mapear roles: inbound = user, outbound = assistant
const historial = historyItems
  .filter(m => m.json && m.json.content)
  .sort((a, b) => new Date(a.json.created_at).getTime() - new Date(b.json.created_at).getTime())
  .map(m => ({
    role: m.json.direction === 'inbound' ? 'user' : 'assistant',
    content: m.json.content
  }))
  // Excluir el último mensaje (el actual que acaba de entrar)
  // ya lo agregamos manualmente abajo como el mensaje actual
  .slice(0, -1);

// ── Array final para OpenAI ──
const openaiMessages = [
  { role: 'system', content: systemPrompt },
  ...historial,
  { role: 'user', content: incoming.message }
];

return [{
  json: {
    openaiMessages,
    professional,
    incoming,
    estaAbierto,
    notificationPhone: businessConfig.orders_notification_phone || null,
    businessName,
    conversation_id: apiResponse.conversation_id,
    patient_id: apiResponse.patient_id
  }
}];

