        "parameters": {
          "type": "object",
          "properties": {
            "client_name": { "type": "string", "description": "Nombre del cliente" },
            "order_details": { "type": "string", "description": "Descripción completa del pedido con cantidades y platillos" },
            "delivery_type": { "type": "string", "description": "recoger o domicilio" },
            "delivery_address": { "type": "string", "description": "Dirección de entrega. Si es para recoger, valor: para recoger" },
            "payment_method": { "type": "string", "description": "efectivo, tarjeta o transferencia" },
            "requested_time": { "type": "string", "description": "Hora estimada en formato ISO 8601. Si no especifica, usar NOW + 30 minutos." }
          },
          "required": ["client_name", "order_details", "delivery_type", "delivery_address", "payment_method", "requested_time"]
        }
      }
    },
    {
      "type": "function",
      "function": {
        "name": "Send_Menu_Image",
        "description": "Envía la imagen del menú al cliente SOLO cuando lo solicita explícitamente con palabras como foto, imagen o menú visual.",
        "parameters": {
          "type": "object",
          "properties": {
            "reason": { "type": "string", "description": "Motivo por el que se envía la imagen" }
          },
          "required": ["reason"]
        }
      }
    }
  ]
}

